// Parity tests for histogram.js (and the summary.js metric/summary functions) against the real
// cloudrun handlers (expected values generated by calling main.histogram / main.histogram_compare /
// analysis.summarize_dataset in the venv python; the generating scripts are reproduced at the
// bottom of this file as a comment).
import { describe, it, expect } from 'vitest'
import {
  buildBins, valueRange, unitForMetric, histogramSeries, histogramFromStored, compareFromStored,
} from '../histogram.js'
import {
  metricValues, metricWeights, attainableMass, extractionYield, filterByMinDiameter,
  commonMinDiameterUm, summarizeDataset, summaryOrNone, particlesPayload,
} from '../summary.js'
import { makeDataset } from '../dataset.js'
import { mulberry32 } from '../prng.js'

// Same synthetic dataset as synth.py / gen_summary.py (only + and * so inputs are bit-identical).
function makeSynthetic(seed, n, edge, scale, meta = {}, label = 'Current Data') {
  const u = mulberry32(seed)
  const c = { surface: [], roundness: [], short_axis: [], long_axis: [], volume: [], xmean: [], ymean: [], edge_weight: [], cluster_id: [] }
  for (let i = 0; i < n; i++) {
    const r = Array.from({ length: 9 }, () => u())
    const surface = 6.0 + 3000.0 * r[0] * r[1]
    const longAxis = 2.0 + 60.0 * r[2] * r[3]
    const shortAxis = longAxis * (0.4 + 0.5 * r[4])
    const volume = surface * (1.0 + 20.0 * r[5]) * (0.5 + longAxis * r[6] * 0.2)
    c.cluster_id.push(i * 2 + 1)
    c.surface.push(surface)
    c.long_axis.push(longAxis)
    c.short_axis.push(shortAxis)
    c.volume.push(volume)
    c.roundness.push(0.3 + 0.7 * r[7])
    c.xmean.push(r[8] * 1000.0)
    c.ymean.push(r[0] * 1500.0)
    c.edge_weight.push(edge ? (1.0 + 4.0 * r[1] * r[8]) : 1.0)
  }
  return makeDataset(c, { pixel_scale: scale, label, meta: { ...meta } })
}

const rel = (a, b, tol, what) => {
  if (a === null || b === null) { expect(a, what).toBe(b); return }
  if (!(Math.abs(a - b) <= tol * Math.max(Math.abs(a), Math.abs(b), 1e-300))) throw new Error(`${what}: ${a} vs ${b}`)
}

