describe('metrics', () => {
  const ds = makeSynthetic(7, 60, true, 123.456, { min_surface: 5.0 })
  for (const m of ['diameter', 'surface', 'volume', 'extraction_yield']) {
    it(`metricValues ${m}`, () => {
      const got = metricValues(ds, m)
      got.forEach((v, i) => rel(v, E.metric_values[m][i], 1e-14, `${m}[${i}]`))
    })
  }
  for (const w of ['number', 'surface', 'mass', 'available_mass', 'extracted_mass']) {
    it(`metricWeights ${w}`, () => {
      const got = metricWeights(ds, w)
      got.forEach((v, i) => rel(v, E.metric_weights[w][i], 1e-14, `${w}[${i}]`))
    })
  }
  it('errors use the Python messages', () => {
    const noScale = makeSynthetic(1, 5, false, null)
    expect(() => metricValues(noScale, 'diameter')).toThrow(E.metric_err[0])
    expect(() => metricValues(ds, 'bogus')).toThrow(E.metric_err[1])
    expect(() => metricWeights(ds, 'bogus')).toThrow(E.metric_err[2])
    expect(() => metricWeights(noScale, 'number')).toThrow(E.metric_err[3])
  })
  it('scale argument overrides the dataset scale', () => {
    expect(metricValues(ds, 'diameter', 50.0)[0]).toBe(metricValues({ ...ds, pixel_scale: 50.0 }, 'diameter')[0])
  })
  it('attainableMass and extractionYield', () => {
    const vv = [0.0, 1e-4, 0.0041, 0.0042, 0.02, 0.5, 3.0]
    const ss = [1e-3, 0.01, 0.1, 1.0, 5.0, 25.0, 100.0]
    attainableMass(vv).forEach((v, i) => rel(v, E.attain[i], 1e-14, `attain[${i}]`))
    extractionYield(ss).forEach((v, i) => rel(v, E.eyield[i], 1e-14, `eyield[${i}]`))
  })
})

