// ---------------------------------------------------------------- histogram.js
const H = E.hist

// Deep comparison: numbers at rtol; `fractions` must be equal except that the first and last bin
// may differ: the smallest/largest particle sits within an ulp of the outer edge (10**log10(x) is
// not x exactly) and either implementation may then drop it (COMMON.md section 7, risk 7).
function compareResponse(got, exp, path = '', tol = 1e-9, opts = {}) {
  if (exp === null || typeof exp !== 'object') {
    if (typeof exp === 'number') rel(got, exp, tol, path)
    else expect(got, path).toEqual(exp)
    return
  }
  if (Array.isArray(exp)) {
    expect(Array.isArray(got), `${path} is array`).toBe(true)
    expect(got.length, `${path}.length`).toBe(exp.length)
    exp.forEach((e, i) => compareResponse(got[i], e, `${path}[${i}]`, tol, opts))
    return
  }
  expect(Object.keys(got).sort(), `${path} keys`).toEqual(Object.keys(exp).sort())
  for (const k of Object.keys(exp)) {
    if (k === 'edges') {
      compareResponse(got[k], exp[k], `${path}.${k}`, 1e-12, opts)
    } else if (k === 'fractions') {
      expect(got[k].length).toBe(exp[k].length)
      exp[k].forEach((e, i) => {
        if (Math.abs(got[k][i] - e) > 1e-12) {
          expect(i === 0 || i === exp[k].length - 1, `${path}.${k}[${i}] differs (${got[k][i]} vs ${e}), only the outer bins may`).toBe(true)
        }
      })
    } else {
      compareResponse(got[k], exp[k], `${path}.${k}`, tol, opts)
    }
  }
}

describe('helpers', () => {
  it('unitForMetric matches main._unit_for_metric', () => {
    for (const u of H.units) {
      const got = unitForMetric(u.metric, [u.max, -u.max / 2])
      expect(got, `${u.metric} ${u.max}`).toEqual({ scale: u.scale, unit: u.unit, latex_unit: u.latex_unit, axis_label: u.axis_label })
    }
  })
  it('buildBins matches plotting._build_bins', () => {
    for (const b of H.bins) {
      const e = buildBins(b.xmin, b.xmax, b.log, b.bins)
      expect(e.length).toBe(b.n)
      const picks = b.edges.length === 4 && b.n > 30 ? [0, 1, e.length - 2, e.length - 1] : e.map((_, i) => i)
      picks.forEach((idx, j) => rel(e[idx], b.edges[j], b.log ? 1e-14 : 0, `bins[${idx}]`))
    }
  })
  it('valueRange matches main._value_range', () => {
    for (const r of H.ranges) {
      const vals = r.vals.map(row => Float64Array.from(row, v => (v === null ? NaN : v)))
      expect(valueRange(vals, r.metric)).toEqual(r.y)
    }
  })
})

