describe('histogramFromStored', () => {
  for (const [name, c] of Object.entries(SINGLE)) {
    it(name, () => {
      const exp = H.single[name]
      const { id = 1, ...req } = c
      if (exp.err) {
        let caught
        try { histogramFromStored(storedResult(id), req) } catch (e) { caught = e }
        expect(caught?.message).toBe(exp.err)
        expect(caught?.status).toBe(exp.status)
        return
      }
      const got = histogramFromStored(storedResult(id), req)
      compareResponse(got, exp.ok, name)
      // JSON-shaped: plain arrays, no non-finite numbers
      expect(JSON.parse(JSON.stringify(got))).toEqual(got)
      expect(Array.isArray(got.edges ?? got.series.edges)).toBe(true)
    })
  }
  it('does not modify the stored dataset', () => {
    const s = storedResult(1)
    const before = s.dataset.n
    histogramFromStored(s, { removed_cluster_ids: [1, 3], min_diameter_um: 300 })
    expect(s.dataset.n).toBe(before)
  })
  it('histogramSeries conserves normalised weight inside the range', () => {
    const ds = stored[1]()
    const r = histogramSeries([ds], { x_metric: 'diameter', weight_mode: 'number', x_log: true, bins: null })
    const total = r.series[0].fractions.reduce((a, b) => a + b, 0)
    expect(total).toBeGreaterThan(0.99)
    expect(total).toBeLessThanOrEqual(1 + 1e-9)
    expect(r.x_log).toBe(true)
  })
})

